[asy]
unitsize(0.6 cm);

draw((-1,0)--(8,0));
draw((0,-1)--(0,4));
draw(arc((0,0),4*sqrt(3),0,30),red,Arrow(6));
draw((0,0)--(6,2*sqrt(3)));

dot((6,2*sqrt(3)), red);
label("$(6,2 \sqrt{3})$", (6, 2*sqrt(3)), N);
dot((4*sqrt(3),0), red);
[/asy]

